    if not backtest_expected_px or backtest_expected_px <= 0:
        return {"drift_bps": 0.0, "within_band": True, "canary_drift_bps": None,
                "verdict": "no_backtest_px"}
    drift = (shadow_fill_px - backtest_expected_px) / backtest_expected_px * 10000.0
