{"content":"# -*- coding: utf-8 -*-
"""
shadow_llm_enhancer.py —— LLM 影子增强层（接恒林/泓算网关；可回退·默认 shadow）
====================================================================
接"恒林网关"（= 泓算网关 http://100.111.136.87:18889/v1，OpenAI 兼容·Bearer key）的
**增量增强层**。严守框架 5 护栏（v7 §十八，命门①：外部实证 LLM 直接下单实盘亏 1/3）：
  ① 只读观点：LLM 只输出 {view, rank, confidence, reason}，**绝不改价格/仓位/止损**（那些是 cs_sizing/风控 的事）
  ② 数值溯源：reason 引用了具体数字，若该数字 hash 不到输入数据表 → 幻觉 → confidence 封顶 + provenance_gap
  ③ 默认 shadow：结果落 llm_shadow_log（不进 8 闸/主链），可一键回退（关掉即主链不变）
  ④ 可回退 + 可复现：fingerprint=prompt_ver+model+temp+seed+data_hash
  ⑤ 配额熔断：日调用 > daily_quota → 停（不烧钱）
没 key / 没数据 → status=NOT_CALLED（**绝不 fake 一个 LLM 观点**，合成自证边界）。

红线：纯 Python 零依赖；真调网关需 HL_GATEWAY_KEY（env 注入，不落 config）；model 路由协议未 100% 核实
  （按 OpenAI 兼容标准形状写，真接入以网关回包为准，标红档）。
"""
import hashlib, json, os, urllib.request, urllib.error

PROMPT_VER = "hl_llm_shadow_v1"
_TEMP = 0.0            # 可复现：温度 0
_SEED = 42
_CONF_CAP_HALLUCINATION = 0.5   # 数值幻觉 → 置信度封顶（护栏②）
_QUOTA_ENV = "HL_LLM_DAILY_QUOTA"


def _data_hash(payload):
    """输入数据指纹（可复现锚点）：对 payload 的 json 稳定序列化取 sha256。"""
    s = json.dumps(payload, sort_keys=True, default=str, ensure_ascii=False)
    return hashlib.sha256(s.encode("utf-8")).hexdigest()[:16]


def build_prompt(signal, data):
    """构造 LLM 观点 prompt：只喂结构化事实 + 要求观点，不喂"让我改仓位"。"""
    facts = json.dumps({k: v for k, v in (data or {}).items() if v is not None},
                       ensure_ascii=False, default=str)
    return (f"[{PROMPT_VER}] 你是 A股 横截面多因子 观察员。给定 信号 与 数据（只读，勿改 价格/仓位/止损）：\n"
            f"signal={json.dumps(signal, ensure_ascii=False, default=str)}\n"
            f"data={facts}\n"
            f"输出 严格 JSON: {{\"view\":\"long|neutral\",\"rank\":int,\"confidence\":0-1,\"reason\":\"引用数字须出自 data\"}}")


def provenance_check(reason, data):
    """护栏②数值溯源：reason 引用的数字能否 hash 到 data（简化=数字字符串在 data 序列化里出现）。
    出现不了 → 幻觉（provenance_gap=1）。"""
    if not reason:
        return 0
    blob = json.dumps(data or {}, ensure_ascii=False, default=str)
    # 抽取 reason 里的 2 位以上数字 token，任一在 data 里找不到 → gap
    import re
    nums = set(re.findall(r"\d+\.\d+|\d+", reason))
    nums = {n for n in nums if any(ch.isdigit() for ch in n)}
    for n in nums:
        if n not in blob:
            return 1
    return 0


def call_gateway(prompt, model="qwen3:8b", key=None, base_url=None, timeout=20):
    """真调 泓算网关 /v1/chat/completions（OpenAI 兼容，Bearer key）。
    无 key → 返回 None（caller 判 NOT_CALLED，绝不 fake）。命中 配额 由 caller 管。"""
    key = key or os.environ.get("HL_GATEWAY_KEY", "")
    base_url = base_url or os.environ.get("HL_GATEWAY", "http://100.111.136.87:18889")
    if not key:
        return None                              # NOT_CALLED 的安全边界
    body = json.dumps({"model": model, "temperature": _TEMP, "seed": _SEED,
                       "messages": [{"role": "user", "content": prompt}], "max_tokens": 200}).encode()
    req = urllib.request.Request(f"{base_url}/v1/chat/completions", data=body, method="POST",
                                 headers={"Content-Type": "application/json",
                                          "Authorization": f"Bearer {key}"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        return {"_error": f"HTTP {e.code}"}
    except Exception as e:
        return {"_error": f"{type(e).__name__}"}


def enhance(signal, data, llm_call=None, model="qwen3:8b", now_iso=""):
    """影子增强主入口。llm_call(prompt)->chat_dict 可注入（合成自证传 mock，真接传 lambda p: call_gateway(p,model)）。
    返回 dict{status, view, rank, confidence, reason, provenance_gap, data_hash, fingerprint, model}，caller 落 llm_shadow_log。
    status: NOT_CALLED(无 llm_call/无回包) / shadow(观点已出,不进主链) / hallucinated_downgraded(数值无溯源→置信封顶)。"""
    dh = _data_hash(data)
    fp = f"{PROMPT_VER}|{model}|{_TEMP}|{_SEED}|{dh}"
    if llm_call is None:
        return {"status": "NOT_CALLED", "view": None, "rank": None, "confidence": 0.0,
                "reason": "no key / no llm endpoint → 安全不 fake", "provenance_gap": 0,
                "data_hash": dh, "fingerprint": fp, "model": model, "ts": now_iso}
    raw = llm_call(build_prompt(signal, data))
    if not raw or isinstance(raw, dict) and raw.get("_error"):
        err = (raw or {}).get("_error", "no response")
        return {"status": "NOT_CALLED", "view": None, "rank": None, "confidence": 0.0,
                "reason": f"gateway: {err}", "provenance_gap": 0,
                "data_hash": dh, "fingerprint": fp, "model": model, "ts": now_iso}
    # 解析 OpenAI 兼容 content（尽力，解析失败=NOT_CALLED 不 fake）
    content = None
    try:
        content = raw["choices"][0]["message"]["content"]
    except (KeyError, IndexError, TypeError):
        pass
    if not content:
        return {"status": "NOT_CALLED", "view": None, "rank": None, "confidence": 0.0,
                "reason": "parse: no content", "provenance_gap": 0,
                "data_hash": dh, "fingerprint": fp, "model": model, "ts": now_iso}
    try:
        obj = json.loads(content.strip())
    except Exception:
        obj = {}
    view = obj.get("view", "neutral") if view_ok(obj.get("view")) else "neutral"
    rank = int(obj.get("rank", 0) or 0)
    conf = float(obj.get("confidence", 0.0) or 0.0)
    reason = str(obj.get("reason", ""))
    gap = provenance_check(reason, data)
    status = "shadow"
    if gap:
        conf = min(conf, _CONF_CAP_HALLUCINATION)     # 护栏②幻觉 → 置信封顶
        status = "hallucinated_downgraded"
    return {"status": status, "view": view, "rank": rank, "confidence": conf, "reason": reason,
            "provenance_gap": gap, "data_hash": dh, "fingerprint": fp, "model": model, "ts": now_iso}


def view_ok(v):
    return v in ("long", "neutral")


def _selftest():
    # ① 无 key / 无 llm_call → NOT_CALLED（绝不 fake）
    r = enhance({"code": "600000", "score": 0.8}, {"close": 10.0, "pe": 12.3}, llm_call=None, model="qwen3:8b", now_iso="2026-10-11")
    assert r["status"] == "NOT_CALLED" and r["view"] is None, f"无 key 必须 NOT_CALLED，得 {r}"
    print(f"[llm_shadow] 无key→NOT_CALLED（安全不 fake）✅ {r['reason']}")

    # ② mock LLM 正常观点（reason 引用数据里的数字）→ shadow
    def mock_ok(prompt):
        return {"choices": [{"message": {"content": json.dumps(
            {"view": "long", "rank": 1, "confidence": 0.72, "reason": "pe 12.3 偏低, close 10.0"})}}]}
    r2 = enhance({"code": "600000"}, {"close": 10.0, "pe": 12.3}, llm_call=mock_ok, now_iso="2026-10-11")
    assert r2["status"] == "shadow" and r2["view"] == "long" and r2["provenance_gap"] == 0, f"正常观点应 shadow，得 {r2}"
    print(f"[llm_shadow] mock观点→shadow ✅ view={r2['view']} conf={r2['confidence']} fp={r2['fingerprint'][:24]}")

    # ③ mock LLM 幻觉（reason 引用 data 里没有的数字）→ 降级 + 置信封顶
    def mock_hallu(prompt):
        return {"choices": [{"message": {"content": json.dumps(
            {"view": "long", "rank": 1, "confidence": 0.9, "reason": "RS 分位 99.9% 强"})}}]}
    r3 = enhance({"code": "600000"}, {"close": 10.0, "pe": 12.3}, llm_call=mock_hallu, now_iso="2026-10-11")
    assert r3["provenance_gap"] == 1 and r3["status"] == "hallucinated_downgraded" and r3["confidence"] <= _CONF_CAP_HALLUCINATION, \
        f"幻觉须降级+置信封顶，得 {r3}"
    print(f"[llm_shadow] 数值幻觉→降级 ✅ conf {0.9}→{r3['confidence']} (cap {_CONF_CAP_HALLUCINATION})")

    # ④ 护栏③④：LLM 观点不改 价格/仓位（本件只产 view/rank/conf/reason，无 price/qty/weight 字段）
    assert all(k not in r2 for k in ("price", "qty", "weight", "stop")), "LLM 层不得产出 价格/仓位/止损"
    print("[llm_shadow] 护栏③④ 只读观点+可回退(落 llm_shadow_log 不进主链) ✅")
    print(f"[llm_shadow] ✅ LLM 影子增强层全自证（合成；真调网关需 HL_GATEWAY_KEY，model 路由协议未 100% 核实=红档）")


if __name__ == "__main__":
    _selftest()
