# 对拍：把引擎 _weights_inverse_vol 的纯逻辑(1/σ+cap+归一)当参考, 验 cs_sizing 与之一致
import math
def ref(vols,N):
    inv={c:(1.0/vols[c]) if vols.get(c,0)>0 else 0.0 for c in vols}
    s=sum(inv.values())
    if s<=0: return {c:1.0/max(1,len(vols)) for c in vols}
    w={c:inv[c]/s for c in vols}; cap=(1.0/max(1,N))*1.5
    w={c:min(w[c],cap) for c in vols}; s2=sum(w.values())
    return {c:(w[c]/s2 if s2>0 else 0) for c in w}
