def shadow_verify(order, backtest_expected_px, shadow_fill_px, canary_fill_px=None,
                  threshold_bps=5.0):
    """#120 验证循环：回测假设价 vs 模拟成交价 vs canary 真单价，三方对比 + 漂移报警。
    回测若用 T 日收盘成交=偷隔夜(年化虚高 10-11pp，#120 E2)；本函数把"模拟成交价(T+1 open)
