def run(self):
    """依序跑 5 流，每步门禁；关键步 fail 停后续。返回 pipeline_status 摘要。"""
    plan = [("data", self.step_data), ("signal", self.step_signal), ("decision", self.step_decision),
            ("execution", self.step_execution), ("reconcile", self.step_reconcile)]
    hard_stop = {"data", "reconcile"}   # 这两步 fail 即停（数据坏/闭环断=别往下走）
    summary = {}
    for name, fn in plan:
        try:
            ok = fn()
            summary[name] = "ok" if ok else "fail"
        except Exception as e:
            self._log(name, "fail", 1, f"exc:{e}")
            summary[name] = "fail"
            if name in hard_stop:
                break
            continue
        if not ok and name in hard_stop:
            break
    self.conn.close()
    print(f"[daily_pipeline] {self.asof} dry_run={self.dry_run} → {summary}")
    return summary

