    """EOD 撤单（#120）：未成交的 pending/queued/blocked 订单 15:00 清空、绝不跨日。
    open_orders: [dict] execution_log 行（含 state）。返回同长 list，未成交者置 state='cancelled_eod'。
    filled 的不动。次日重新生成信号，不沿用隔夜挂单。"""
    for o in open_orders:
        if o.get("state") in ("pending", "submitted", "queued_uplimit", "queued_downlimit",
                              "blocked", "blocked_oneword"):
            o["state"] = "cancelled_eod"
            o["cancel_reason"] = "EOD撤单(未成交, 不跨日)"
            o.setdefault("note", "") += " [EOD撤单@%s]" % asof
    return open_orders

def shadow_verify(order, backtest_expected_px, shadow_fill_px, canary_fill_px=None,
                  threshold_bps=5.0):
    """#120 验证循环：回测假设价 vs 模拟成交价 vs canary 真单价，三方对比 + 漂移报警。
    回测若用 T 日收盘成交=偷隔夜(年化虚高 10-11pp，#120 E2)；本函数把"模拟成交价(T+1 open)
    相对回测假设价的漂移"量化，超 threshold_bps 即报警。canary_fill_px=None 时(未进真单)跳过第三边。
    返回 dict{drift_bps, within_band, canary_drift_bps, verdict}。"""
    if not backtest_expected_px or backtest_expected_px <= 0:
        return {"drift_bps": 0.0, "within_band": True, "canary_drift_bps": None,
                "verdict": "no_backtest_px"}
    drift = (shadow_fill_px - backtest_expected_px) / backtest_expected_px * 10000.0
    within = abs(drift) <= threshold_bps
    canary = None
    if canary_fill_px:
        canary = (canary_fill_px - backtest_expected_px) / backtest_expected_px * 10000.0
    verdict = "ok" if within else "DRIFT>%.0fbp→查(数据/推理/策略/执行/运维 五桶归因)" % threshold_bps
    return {"drift_bps": round(drift, 2), "within_band": within,
            "canary_drift_bps": (round(canary, 2) if canary is not None else None),
            "verdict": verdict}


